void main() => runApp(const HabitTrackerApp());

class AppColors {
  static const navy = Color(0xFF102A43), blue = Color(0xFF1769FF), blueSoft = Color(0xFFEAF1FF), bg = Color(0xFFF5F7FB), text = Color(0xFF142033), muted = Color(0xFF718096), border = Color(0xFFE6EAF0), green = Color(0xFF16A36A), orange = Color(0xFFF59E0B);
