class HabitTrackerApp extends StatelessWidget {
  const HabitTrackerApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    title: 'Habit Tracker', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: AppColors.blue), scaffoldBackgroundColor: AppColors.bg),
    home: const AppShell(),
  );
}

class AppShell extends StatefulWidget { const AppShell({super.key}); @override State<AppShell> createState() => _AppShellState(); }
class _AppShellState extends State<AppShell> {
  final storage = StorageService(); List<Habit> habits = []; List<Map<String,dynamic>> todos = []; Map<String,int> moods = {}; Map<String,int> timerSeconds = {}; String? pin; bool locked=false; int tab=0; DateTime selectedDate=DateTime.now(); String search='';
  @override void initState(){super.initState(); _load();}
  Future<void> _load() async { final h=await storage.loadHabits(), t=await storage.loadTodos(), m=await storage.loadMoods(), ts=await storage.loadTimerSeconds(), p=await storage.loadPin(); if(!mounted)return; setState((){habits=h; todos=t; moods=m; timerSeconds=ts; pin=p; locked=p!=null;}); }
  Future<void> saveH()=>storage.saveHabits(habits);
  Future<void> toggle(Habit h,[DateTime? d])async{final day=d??selectedDate;setState(()=>h.setDone(day,!h.isDone(day)));await saveH();}
  Future<void> addHabit()async{final r=await showModalBottomSheet<HabitEditResult>(context:context,isScrollControlled:true,backgroundColor:Colors.white,builder:(_)=>const HabitEditorSheet());if(!mounted||r==null||r.name.trim().isEmpty)return;setState(()=>habits.add(r.toHabit()));await saveH();}
  Future<void> editHabit(Habit h)async{final r=await showModalBottomSheet<HabitEditResult>(context:context,isScrollControlled:true,backgroundColor:Colors.white,builder:(_)=>HabitEditorSheet(habit:h));if(!mounted||r==null)return;if(r.delete){final ok=await confirm(context,'Delete habit?','Remove "${h.name}" from your tracker?');if(ok){setState(()=>habits.removeWhere((x)=>x.id==h.id));await saveH();}return;}h.name=r.name;h.category=r.category;h.goal=r.goal;h.unit=r.unit;h.frequency=r.frequency;h.weekdays=r.weekdays;h.pinned=r.pinned;h.tags=r.tags;h.notes=r.notes;setState((){});await saveH();}
  Future<void> openHabit(Habit h)async{await showModalBottomSheet(context:context,isScrollControlled:true,backgroundColor:Colors.white,builder:(_)=>HabitDetailSheet(habit:h,date:selectedDate,onChanged:()async{setState((){});await saveH();}));}
  Future<void> addTodo()async{final r=await showDialog<TodoEditResult>(context:context,builder:(_)=>const TodoEditorDialog());if(!mounted||r==null||r.title.trim().isEmpty)return;setState(()=>todos.add({'id':DateTime.now().microsecondsSinceEpoch.toString(),'title':r.title.trim(),'done':false,'priority':r.priority,'category':r.category,'due':r.due==null?'':Habit.key(r.due!)}));await storage.saveTodos(todos);}
  Future<void> editTodo(int i)async{final old=todos[i];final r=await showDialog<TodoEditResult>(context:context,builder:(_)=>TodoEditorDialog(initial:old));if(!mounted||r==null)return;if(r.delete)setState(()=>todos.removeAt(i));else setState((){old['title']=r.title.trim();old['priority']=r.priority;old['category']=r.category;old['due']=r.due==null?'':Habit.key(r.due!);});await storage.saveTodos(todos);}
  Future<void> mood(int v)async{setState(()=>moods[Habit.key(selectedDate)]=v);await storage.saveMoods(moods);}
  Future<void> timer()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>FocusTimerPage(storage:storage,date:selectedDate,initialSeconds:timerSeconds[Habit.key(selectedDate)]??0,onSaved:(s)=>setState(()=>timerSeconds[Habit.key(selectedDate)]=s))));}
  Future<void> setPin()async{final r=await showDialog<String>(context:context,builder:(_)=>const PinDialog());if(r==null)return;pin=r.isEmpty?null:r;await storage.savePin(pin);if(mounted)setState(()=>locked=pin!=null);}
  @override Widget build(BuildContext context){if(locked)return LockScreen(onUnlock:(v){if(v==pin)setState(()=>locked=false);});final pages=[DashboardPage(habits:habits,todos:todos,moods:moods,date:selectedDate,search:search,onSearchChanged:(v)=>setState(()=>search=v),onToggle:toggle,onAdd:addHabit,onEdit:editHabit,onOpen:openHabit,onMood:mood,onTimer:timer),DailyPage(habits:habits,date:selectedDate,onDateChanged:(d)=>setState(()=>selectedDate=d),onToggle:toggle,onAdd:addHabit,onEdit:editHabit,onOpen:openHabit,onTimer:timer),AnalyticsPage(habits:habits,moods:moods,todos:todos,onAchievements:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AchievementsPage(habits:habits)))),TodoPage(todos:todos,onAdd:addTodo,onEdit:editTodo,onChanged:()async{setState((){});await storage.saveTodos(todos);}),ProfilePage(habits:habits,todos:todos,onPin:setPin,onTimer:timer)];return Scaffold(body:SafeArea(child:IndexedStack(index:tab,children:pages)),bottomNavigationBar:NavigationBar(height:72,selectedIndex:tab,backgroundColor:Colors.white,indicatorColor:AppColors.blueSoft,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.check_circle_outline),selectedIcon:Icon(Icons.check_circle),label:'Habits'),NavigationDestination(icon:Icon(Icons.insights_outlined),selectedIcon:Icon(Icons.insights),label:'Stats'),NavigationDestination(icon:Icon(Icons.list_alt_outlined),selectedIcon:Icon(Icons.list_alt),label:'To-Do'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Profile')]));}
}

