}

class HabitTile extends StatelessWidget { final Habit habit; final DateTime date; final VoidCallback onToggle,onEdit,onOpen; const HabitTile({super.key,required this.habit,required this.date,required this.onToggle,required this.onEdit,required this.onOpen}); @override Widget build(BuildContext context){final done=habit.isDone(date);final rate=habit.completionRate(date).clamp(0.0,1.0);return GestureDetector(onLongPress:onEdit,onTap:onOpen,child:SurfaceCard(padding:const EdgeInsets.all(15),child:Row(children:[GestureDetector(onTap:onToggle,child:Container(width:40,height:40,decoration:BoxDecoration(color:done?AppColors.blue:AppColors.blueSoft,shape:BoxShape.circle),child:Icon(done?Icons.check:iconFor(habit.icon),color:done?Colors.white:AppColors.blue))),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(habit.name,style:TextStyle(fontWeight:FontWeight.w900,decoration:done?TextDecoration.lineThrough:null))),if(habit.pinned)const Icon(Icons.push_pin,size:16,color:AppColors.orange)]),Wrap(spacing:4,children:[Chip(label:Text(habit.category),visualDensity:VisualDensity.compact),Chip(label:Text('${habit.goal} ${habit.unit} · ${habit.frequency}'),visualDensity:VisualDensity.compact),if(habit.currentStreak(date)>0)Text('🔥${habit.currentStreak(date)}',style:const TextStyle(fontWeight:FontWeight.w800))]),LinearProgressIndicator(value:rate,minHeight:5,backgroundColor:AppColors.blueSoft)])),const Icon(Icons.chevron_right,color:AppColors.muted)])));}}

