String priorityName(int p)=>p==3?'High':p==2?'Medium':'Low';
IconData iconFor(String name){switch(name){case 'fitness':return Icons.fitness_center;case 'book':return Icons.menu_book;case 'water':return Icons.water_drop;case 'self_improvement':return Icons.self_improvement;default:return Icons.check_circle;}}
